head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[localStorage > M > getAllItem]<br/>localStorage 에 저장된 모든 데이터를 JSON 객체로 반환합니다.",
    "validation" : [
        "localStorage 의 모든 key-value 쌍을 포함하는 Object 를 반환해야 합니다.",
        "저장된 데이터가 없으면 빈 Object 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);

    // 기존 데이터 초기화
    WebSquare.localStorage.clear();
};



scwin.btn_getAllItem_onclick = function () {
    let result = WebSquare.localStorage.getAllItem();

    wf_body_bottom.getObj("scwin").setReturnValue("getAllItem() 결과 :");
    wf_body_bottom.getObj("scwin").setReturnValue(JSON.stringify(result, null, 2));
    wf_body_bottom.getObj("scwin").setReturnValue("typeof : " + typeof result);

    // 특정 키 존재 여부로 검증
    let has1 = result.hasOwnProperty("allItemTest1");
    let has2 = result.hasOwnProperty("allItemTest2");
    let has3 = result.hasOwnProperty("allItemTest3");
    wf_body_bottom.getObj("scwin").setReturnValue("allItemTest1 포함 : " + has1);
    wf_body_bottom.getObj("scwin").setReturnValue("allItemTest2 포함 : " + has2);
    wf_body_bottom.getObj("scwin").setReturnValue("allItemTest3 포함 : " + has3);
    wf_body_bottom.getObj("scwin").setReturnValue("저장 데이터 포함 확인 : " + (has1 && has2 && has3 ? "PASS" : "FAIL"));
}



scwin.btn_setTestData_onclick = function () {
    WebSquare.localStorage.setItem("allItemTest1", "value1");
    WebSquare.localStorage.setItem("allItemTest2", "value2");
    WebSquare.localStorage.setItem("allItemTest3", "value3");
    wf_body_bottom.getObj("scwin").setReturnValue("테스트 데이터 3건 저장 완료 (allItemTest1~3)");
}



scwin.btn_clearTestData_onclick = function () {
    WebSquare.localStorage.removeItem("allItemTest1");
    WebSquare.localStorage.removeItem("allItemTest2");
    WebSquare.localStorage.removeItem("allItemTest3");

    // 삭제 후 getAllItem 으로 미포함 확인
    let result = WebSquare.localStorage.getAllItem();
    let has1 = result.hasOwnProperty("allItemTest1");
    let has2 = result.hasOwnProperty("allItemTest2");
    let has3 = result.hasOwnProperty("allItemTest3");
    wf_body_bottom.getObj("scwin").setReturnValue("테스트 데이터 삭제 완료");
    wf_body_bottom.getObj("scwin").setReturnValue("삭제 확인 : " + (!has1 && !has2 && !has3 ? "PASS" : "FAIL"));
}
